 transmit(tx,acks,vec![owner_body(2,b"OtherRoomOwner")])?;let b=at(r,5);assert_eq!(b.owner_display,Some(owner_receipt.clone()));assert_eq!(b.last_stream_change,Some(members::Change::IgnoredOwnerOtherRoom));
