 let cc=hex(data["next_CC"].as_str().unwrap());let late=epoch.decoded_java_room_tail(&cf)?;
 transmit(tx,acks,vec![cc.clone(),cf.clone()])?;until(r,|r|r.source_connection_epoch().is_none());let rejection=r.last_source_rejection().unwrap();assert_eq!(rejection.opcode,Some(204));assert_eq!(rejection.body_bytes,cc.len());assert_eq!(r.last_java_room_participants_checkpoint(),Some(invalidated));assert_eq!(r.last_java_room_catalog_checkpoint(),Some(catalog_checkpoint));
