 cases.push(json!({"case":"saved real S_CC reset body remains first unsupported candidate wire body; subsequent CF tail not applied; archived7 participant+4 catalog arrivals, stale/fresh scope rejected; no CC replacement/native equivalence inferred","pass":true,"opcode":"CC","body_bytes":cc.len(),"reason":rejection.reason,"same_saved_server_stream_claimed":false}));Ok(cases)
